import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('rejects missing required property and does not call executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;

    registry.register(
      {
        name: 'test_tool',
        description: 'Test tool',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'result';
      }
    );

    const response = await registry.execute('test_tool', {});

    expect(executorCalls).toBe(0);
    expect(response.result).toContain('location');
  });

  it('passes valid input with extra properties through to executor unchanged', async () => {
    const registry = new ToolRegistry();
    let capturedInput: Record<string, unknown> | undefined;

    registry.register(
      {
        name: 'test_tool',
        description: 'Test tool',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async (input) => {
        capturedInput = input;
        return 'result';
      }
    );

    const testInput = {location: 'Paris', extra_field: 'should_pass_through', another: 42};
    const response = await registry.execute('test_tool', testInput);

    expect(capturedInput).toEqual(testInput);
    expect(response.result).toBe('result');
  });

  it('compiles static schema once across multiple execute calls', async () => {
    const registry = new ToolRegistry();
    const compileCallCounts = new Map<string, number>();

    const originalCompile = (registry as any).ajv.compile.bind((registry as any).ajv);
    (registry as any).ajv.compile = (schema: unknown) => {
      const key = JSON.stringify(schema);
      compileCallCounts.set(key, (compileCallCounts.get(key) ?? 0) + 1);
      return originalCompile(schema);
    };

    registry.register(
      {
        name: 'test_tool',
        description: 'Test tool',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => 'result'
    );

    const schemaKey = JSON.stringify({
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    });
    const compileCountBeforeExecutes = compileCallCounts.get(schemaKey) ?? 0;

    await registry.execute('test_tool', {location: 'Paris'});
    await registry.execute('test_tool', {location: 'London'});
    await registry.execute('test_tool', {location: 'Berlin'});

    const compileCountAfterExecutes = compileCallCounts.get(schemaKey) ?? 0;

    expect(compileCountAfterExecutes - compileCountBeforeExecutes).toBe(0);
  });

  it('throws Unknown tool error for unregistered tool name', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('nonexistent_tool', {})).rejects.toThrow('Unknown tool: nonexistent_tool');
  });
});

